head.script:
scwin.unitTest = function() {
    //Init test
    WebSquare.wUnit.start();
    //Test step 1. Source 탭 또는 Property 탭에서 readOnly 부분을 확인한다.- 1. Check the readOnly portion of the Source tab or Property tab.           
    //Verify 1. readOnly = "true"                     
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 2. placeholder 부분을 확인한다.-Identify the placeholder part.
    //Verify 2. placeholder='플레이스 홀더 테스트' - placeholder = 'Placeholder test'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getAttribute('placeholder') == '플레이스 홀더 테스트'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 3. showPlaceHolderOnReadOnly 부분을 확인한다.- Check the showPlaceHolderOnReadOnly part.      
    //Verify    3. showPlaceHolderOnReadOnly='true'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getAttribute('showPlaceHolderOnReadOnly')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getAttribute('placeholder') == '플레이스 홀더 테스트'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create by Truong.Luu
    //Create date 23-Jan-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
